-- Original aMR building descriptors and account-owned Ranch placement state.
CREATE TABLE native_ranch_building_definitions (
 reference integer PRIMARY KEY CHECK(reference>0),
 descriptor jsonb NOT NULL CHECK(jsonb_typeof(descriptor)='object'),
 source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$')
);
CREATE TABLE account_ranch_sectors (
 account_id bigint NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 biome_id integer NOT NULL CHECK(biome_id>0),
 sector_id integer NOT NULL CHECK(sector_id>=0),
 initialized_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(account_id,biome_id,sector_id)
);
CREATE TABLE account_ranch_buildings (
 uid bigint PRIMARY KEY CHECK(uid>0),
 account_id bigint NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 biome_id integer NOT NULL CHECK(biome_id>0),
 sector_id integer NOT NULL CHECK(sector_id>=0),
 building_ref integer NOT NULL REFERENCES native_ranch_building_definitions(reference),
 mode_id integer NOT NULL CHECK(mode_id>=0),
 view_kind smallint NOT NULL CHECK(view_kind IN(0,1)),
 view_value integer NOT NULL,
 x integer NOT NULL,
 y integer NOT NULL,
 contained_item_ref integer NOT NULL DEFAULT -1,
 contained_quantity integer NOT NULL DEFAULT 0 CHECK(contained_quantity>=0),
 revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(account_id,biome_id,sector_id) REFERENCES account_ranch_sectors(account_id,biome_id,sector_id)
);
CREATE INDEX account_ranch_buildings_scene ON account_ranch_buildings(account_id,biome_id,uid);
CREATE TABLE account_ranch_building_tombstones (
 uid bigint PRIMARY KEY CHECK(uid>0),
 account_id bigint NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 biome_id integer NOT NULL CHECK(biome_id>0),
 sector_id integer NOT NULL CHECK(sector_id>=0),
 building_ref integer NOT NULL REFERENCES native_ranch_building_definitions(reference),
 revision bigint NOT NULL CHECK(revision>=0),
 removed_at timestamptz NOT NULL DEFAULT now()
);
